  @Test(timeout = 4000)
  public void writePoint_serializesPoint_andLeavesPointUnchanged() throws Throwable {
    JtsSpatialContextFactory factory = new JtsSpatialContextFactory();
    JtsSpatialContext context = factory.newSpatialContext();
    JtsBinaryCodec codec = newCodec(factory, context);

    ObjectOutputStream output =
        new ObjectOutputStream(new MockPrintStream("Expected initial read of one byte, not: "));
    PointImpl point = new PointImpl(10.0, 3877.7633, context);

    codec.writePoint(output, point);

    // Writing must not mutate the source point's coordinates.
    assertEquals(10.0, point.getLon(), 0.01);
  }

  @Test(timeout = 4000)
  public void writeShapeByTypeIfSupported_returnsFalse_forNullShapeWithUnsupportedType() throws Throwable {
    JtsSpatialContextFactory factory = new JtsSpatialContextFactory();
    JtsSpatialContext context = new JtsSpatialContext(factory);
    JtsBinaryCodec codec = newCodec(factory, context);

    DataOutputStream output = new DataOutputStream(new PipedOutputStream());

    // Type 0 is not the JTS geom type, so the superclass handles it and
    // reports that it did not write the (null) shape.
    boolean written = codec.writeShapeByTypeIfSupported(output, (Shape) null, (byte) 0);

    assertFalse(written);
