    JtsBinaryCodec codec = newCodec(factory, context);

    DataOutputStream output =
        new DataOutputStream(new MockFileOutputStream("Expected initial read of one byte, not: "));
    PointImpl point = new PointImpl(0, 0, context);

    // The JTS geom type is handled by this codec, which writes the geometry
    // and reports success.
    boolean written = codec.writeShapeByTypeIfSupported(output, point, TYPE_GEOM);

    assertTrue(written);
