  @Test(timeout = 4000)
  public void readShapeByTypeIfSupported_throwsOnMalformedJtsGeom() throws Throwable {
    JtsSpatialContextFactory factory = new JtsSpatialContextFactory();
    JtsSpatialContext context = factory.newSpatialContext();
    JtsBinaryCodec codec = newCodec(factory, context);

    DataInputStream input = new DataInputStream(new ByteArrayInputStream(new byte[5]));

    // The JTS geom type triggers WKB parsing of the zero-filled input, which
    // is not valid WKB and surfaces as a RuntimeException ("error reading WKT").
    try {
      codec.readShapeByTypeIfSupported(input, TYPE_GEOM);
      fail("Expecting exception: RuntimeException");
    } catch (RuntimeException e) {
      verifyException("org.locationtech.spatial4j.io.jts.JtsBinaryCodec", e);
    }
  }

