    JtsSpatialContextFactory factory = new JtsSpatialContextFactory();
    JtsBinaryCodec codec = newCodec(factory, context);

    // A null shape is not recognised by the superclass (type 0), so the codec
    // falls back to its catch-all JTS geom type.
    byte type = codec.typeForShape((Shape) null);

    assertEquals(TYPE_GEOM, type);
  }

